function Fila({ estado, nota, children }: { estado: string; nota: string; children: ReactNode }) {
  return (
    <tr>
      <td className="font-semibold whitespace-nowrap">{estado}</td>
      <td>{children}</td>
      <td className="text-ink-medium">{nota}</td>
    </tr>
  )
}

